"""Check the source mask probe generated by render_mask_probe.py."""
from pathlib import Path
import json
import hashlib
import OpenEXR

root=Path(__file__).resolve().parents[3]
stamp=json.loads((root/'.local/depot-mask-probe/inputs.json').read_text())
assert len(stamp)==7
for name,digest in stamp.items():
    assert hashlib.sha256((root/'assets/depots/source'/name).read_bytes()).hexdigest()==digest, f'Stale probe for {name}'
# Older workspaces may retain retired 1x1 probe files. Check only the
# active source-stamped views, without deleting historical outputs.
files=sorted(root/'.local/depot-mask-probe'/f'{Path(name).stem}-{direction}.exr'
             for name in stamp for direction in range(4))
assert all(path.is_file() for path in files), 'Missing active source probe view'
assert len(files)==28, f'Expected 28 source views, found {len(files)}'
checked=0
for path in files:
    with OpenEXR.File(str(path)) as source:
        for channel in ['cab','trim','cargo']:
            name='Vehicle.mask_'+channel+'.X'
            assert source.channels()[name].pixels.max()>0, f'Empty {name} in {path.name}'
            checked+=1
print(json.dumps({'status':'passed','direction_views':len(files),'mask_layers':checked,'resolution':256,'samples':4},indent=2))
